  "meaning": "විචිත්‍ර ගවයන් ඇති (කුලය)",
  "sutta_refs": "සූ. 199, 337",
  "similar_words": "",
  "notes": [
   "‘චිත්තා ගාවො අස්ස කුලස්සා’ති අත්ථෙ බහුබ්බීහිසමාසෙ කතෙ ‘සරො රස්සො නපුංසකෙ’ති ඔකාරස්ස ඨානප්පයතනාසන්නත්තා රස්සත්තමුකාරො. සෙසු රූප ආයු ශබ්දය සමයි."
  ],
